import { taskManager } from './tasks.js';
import { canExport } from './permissions.js';
import { record } from './audit.js';

function escapeCsv(value: string): string {
  if (
    value.includes(',') ||
    value.includes('"') ||
    value.includes('\n') ||
    value.includes('\r')
  ) {
    return `"${value.replace(/"/g, '""')}"`;
  }
  return value;
}

export function exportTasks(userId: string): string {
  if (!canExport(userId)) {
    throw new Error('Forbidden: export not permitted');
  }

  const tasks = Array.from((taskManager as { tasks: Map<string, { createdBy: string }> }).tasks.values());

  record({
    action: 'export',
    userId,
    details: `${tasks.length} tasks exported`,
    timestamp: Date.now(),
  });

  const header = 'id,title,status,assignee,createdAt';
  const rows = tasks.map((t) => {
    const raw = taskManager.getTask(t.id);
    if (!raw) return null;
    return [
      raw.id,
      raw.title,
      raw.status,
      raw.assignee,
      String(raw.createdAt),
    ]
      .map(escapeCsv)
      .join(',');
  }).filter(Boolean);

  return [header, ...rows].join('\n');
